import math

def circle_area(r):
    return math.pi * r ** 2

def rectangle_area(l, w):
    return l * w

def triangle_area(b, h):
    return 0.5 * b * h

def square_area(s):
    return s ** 2

print("Area Calculator")
print("1. Circle")
print("2. Rectangle")
print("3. Triangle")
print("4. Square")

try:
    choice = int(input("Choose shape (1-4): "))
    if choice == 1:
        r = float(input("Radius: "))
        print(f"Area: {circle_area(r):.2f}")
    elif choice == 2:
        l = float(input("Length: "))
        w = float(input("Width: "))
        print(f"Area: {rectangle_area(l, w):.2f}")
    elif choice == 3:
        b = float(input("Base: "))
        h = float(input("Height: "))
        print(f"Area: {triangle_area(b, h):.2f}")
    elif choice == 4:
        s = float(input("Side: "))
        print(f"Area: {square_area(s):.2f}")
    else:
        print("Invalid choice")
except ValueError:
    print("Please enter valid numbers")
